extern "C" void graph_engine_batch(
        const gw_word_t *seed_in,
        gw_word_t       *state_out,
        unsigned        *count_out,
        unsigned         nq,
        unsigned         num_steps) {
#pragma HLS INTERFACE m_axi     port=seed_in   bundle=gmem0 offset=slave depth=1024
#pragma HLS INTERFACE m_axi     port=state_out bundle=gmem1 offset=slave depth=1024
#pragma HLS INTERFACE m_axi     port=count_out bundle=gmem2 offset=slave depth=1024
#pragma HLS INTERFACE s_axilite port=seed_in   bundle=control
#pragma HLS INTERFACE s_axilite port=state_out bundle=control
#pragma HLS INTERFACE s_axilite port=count_out bundle=control
#pragma HLS INTERFACE s_axilite port=nq        bundle=control
#pragma HLS INTERFACE s_axilite port=num_steps bundle=control
#pragma HLS INTERFACE s_axilite port=return    bundle=control

    // GW_PAR rows must be readable in one clock: bank dim 1 by GW_PAR,
    // and keep every lane of a row available at once.
#pragma HLS ARRAY_PARTITION variable=GW_ADJ cyclic factor=GW_PAR dim=1
#pragma HLS ARRAY_PARTITION variable=GW_ADJ complete dim=2
#pragma HLS BIND_STORAGE    variable=GW_ADJ type=rom_1p impl=bram

    const unsigned ksel = (num_steps > GW_STAGES) ? GW_STAGES : num_steps;

    BATCH: for (unsigned q = 0; q < nq; ++q) {
        gw_lane_t cur[GW_NW64], nxt[GW_NW64];
#pragma HLS ARRAY_PARTITION variable=cur complete dim=1
#pragma HLS ARRAY_PARTITION variable=nxt complete dim=1

        CLR: for (unsigned w = 0; w < GW_NW64; ++w) {
#pragma HLS UNROLL
            cur[w] = 0;
        }
        LOADQ: for (unsigned w = 0; w < GW_NW; ++w) {
#pragma HLS UNROLL
            gw_word_t word = seed_in[q * GW_NW + w];
            for (unsigned b = 0; b < GW_WORD_BITS; ++b) {
#pragma HLS UNROLL
                unsigned idx = w * GW_WORD_BITS + b;
                if (idx < GW_N) cur[idx >> 6][idx & 63] = word[b];
            }
        }

        STAGE: for (unsigned k = 0; k < ksel; ++k) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=GW_STAGES
            // One lane at a time. Writing all GW_PAR results straight
            // into nxt[] cost 14.0 ns: every p hit the same array through
            // a VARIABLE lane index, so HLS could not prove independence
            // and built a serial chain of GW_PAR read-modify-writes --
            // measured as GW_PAR x (sparsemux 0.493 + mux 0.675 + mux
            // 0.387 ns) in the HLS 200-1016 critical-path report.
            //
            // Here each p writes its own bit of a private chunk register,
            // and the lane is assembled in a SHIFT REGISTER using constant
            // shifts, so the whole loop-carried recurrence is one 64-bit
            // OR. The expensive AND/reduce feeds it but sits outside it,
            // leaving HLS free to pipeline that part.
            LANE: for (unsigned wi = 0; wi < GW_NW64; ++wi) {
                gw_lane_t acc = 0;
                CHUNK: for (unsigned c = 0; c < GW_LANE_BITS / GW_PAR; ++c) {
#pragma HLS PIPELINE II=1
                    ap_uint<GW_PAR> chunk = 0;
                    for (unsigned p = 0; p < GW_PAR; ++p) {
#pragma HLS UNROLL
                        unsigned v = wi * GW_LANE_BITS + c * GW_PAR + p;
                        if (v < GW_N) {
                            // Reduce as a TREE, not a chain: collapse each
                            // lane to one bit first so the per-lane reduces
                            // run in parallel (~4 logic levels).
                            ap_uint<GW_NW64> hits = 0;
                            for (unsigned w = 0; w < GW_NW64; ++w) {
#pragma HLS UNROLL
                                hits[w] = ((GW_ADJ[v][w] & cur[w]) != 0) ? 1 : 0;
                            }
                            chunk[p] = (hits != 0) ? 1 : 0;
                        }
                    }
                    // Constant shifts: pure wiring. chunk c lands in bits
                    // [c*GW_PAR, c*GW_PAR+GW_PAR) once all chunks are in.
                    acc = (acc >> (int) GW_PAR) | (((gw_lane_t) chunk) << (int) (GW_LANE_BITS - GW_PAR));
                }
                nxt[wi] = acc | cur[wi];
            }
            SWAP: for (unsigned w = 0; w < GW_NW64; ++w) {
#pragma HLS UNROLL
                cur[w] = nxt[w];
            }
        }

        unsigned c = 0;
        CNT: for (unsigned v = 0; v < GW_N; ++v) {
#pragma HLS UNROLL
            c += (unsigned) cur[v >> 6][v & 63];
        }
        count_out[q] = c;

        STOREQ: for (unsigned w = 0; w < GW_NW; ++w) {
#pragma HLS UNROLL
            gw_word_t word = 0;
            for (unsigned b = 0; b < GW_WORD_BITS; ++b) {
#pragma HLS UNROLL
                unsigned idx = w * GW_WORD_BITS + b;
                if (idx < GW_N) word[b] = cur[idx >> 6][idx & 63];
            }
            state_out[q * GW_NW + w] = word;
        }
    }
}
